#include "ui/SceneStack.hpp"
void SceneStack::push(std::unique_ptr<IStackScene>s){m_scenes.push_back(std::move(s));}void SceneStack::pop(){if(!m_scenes.empty())m_scenes.pop_back();}void SceneStack::replace(std::unique_ptr<IStackScene>s){pop();push(std::move(s));}void SceneStack::clearAndPush(std::unique_ptr<IStackScene>s){m_scenes.clear();push(std::move(s));}int SceneStack::size()const{return static_cast<int>(m_scenes.size());}
void SceneStack::update(float dt){if(m_scenes.empty())return;int first=size()-1;while(first>0&&m_scenes[first]->updatesBelow())--first;for(int i=first;i<size();++i)m_scenes[i]->update(dt);}void SceneStack::draw()const{if(m_scenes.empty())return;int first=size()-1;while(first>0&&m_scenes[first]->drawsBelow())--first;for(int i=first;i<size();++i)m_scenes[i]->draw();}
